/**
 * `toDisplay` against oracle measurements generated by
 * `scripts/battery-to-display-fixtures.rb` (`to-display-fixtures.json`).
 *
 * Three kinds of row, kept apart:
 *   - `symbol`: `to_display(:latex)` and friends, the dispatch Opal's
 *     lowercase JS string reaches (`src/compat/to-display.ts`). The port's
 *     lowercase path must reproduce these bytes.
 *   - `nativeString` / `nativeUpcaseString`: native-MRI results for a Ruby
 *     String. Recorded as native-Ruby results only; they are not an Opal
 *     measurement, and the lowercase rows are not what the port returns.
 *   - `invalid`: names outside `MATH_ZONE_TYPES`. The gem raises
 *     `Plurimath::Math::InvalidTypeError`; the port raises
 *     `UnsupportedFormatError`, a recorded divergence (no matching public
 *     error class exists here).
 */
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import Plurimath from "../../src/compat/index";
import { UnsupportedFormatError } from "../../src/core/index";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..");

function sha256OfFile(relativeToRoot: string): string {
  return createHash("sha256")
    .update(readFileSync(join(REPO_ROOT, relativeToRoot)))
    .digest("hex");
}

function pinnedOracleCommit(): string {
  const manifest = readFileSync(join(REPO_ROOT, "corpus/census.manifest.yaml"), "utf8");
  const oracleBlock = manifest.slice(manifest.indexOf("\noracle:\n"));
  const match = oracleBlock.match(/\n {2}commit: ([0-9a-f]{40})\n/);
  if (!match) throw new Error("corpus/census.manifest.yaml: could not find oracle.commit");
  return match[1] as string;
}

interface Outcome {
  readonly result?: string;
  readonly raises?: string;
}

interface FixtureCase {
  readonly input: string;
  readonly symbol: Readonly<Record<string, Outcome>>;
  readonly nativeString: Readonly<Record<string, Outcome>>;
  readonly nativeUpcaseString: Readonly<Record<string, Outcome>>;
  readonly invalid: Readonly<Record<string, Outcome>>;
}

const fixtures = JSON.parse(readFileSync(join(HERE, "to-display-fixtures.json"), "utf8")) as {
  readonly schema: string;
  readonly oracleCommit: string;
  readonly oracleClean: boolean;
  readonly generatorSha256: string;
  readonly casesSha256: string;
  readonly cases: readonly FixtureCase[];
};

const PLACEHOLDER = "|_ Math zone\n";
const LANGS = ["asciimath", "latex", "mathml", "omml", "unicodemath"];

describe("the to_display fixture set", () => {
  it("is the schema this suite reads, from the pinned clean oracle and the committed generator", () => {
    expect(fixtures.schema).toBe("plurimath-compat/to-display/1");
    expect(fixtures.oracleCommit).toBe(pinnedOracleCommit());
    expect(fixtures.oracleClean).toBe(true);
    expect(fixtures.generatorSha256).toBe(sha256OfFile("scripts/battery-to-display-fixtures.rb"));
    expect(createHash("sha256").update(JSON.stringify(fixtures.cases)).digest("hex")).toBe(
      fixtures.casesSha256,
    );
  });

  it("covers exactly the inputs and names the generator lists", () => {
    expect(fixtures.cases.map((row) => row.input)).toEqual([
      "frac(1)(2)",
      "alpha",
      "x^2",
      "sqrt(2)",
      "vec(v)",
      "x+y=2",
    ]);
    for (const row of fixtures.cases) {
      expect(Object.keys(row.symbol)).toEqual(LANGS);
      expect(Object.keys(row.nativeString)).toEqual(LANGS);
      expect(Object.keys(row.nativeUpcaseString)).toEqual(LANGS);
      expect(Object.keys(row.invalid)).toEqual(["html", "unicode"]);
    }
  });
});

describe.each(fixtures.cases)("toDisplay on $input", (row) => {
  const build = () => new Plurimath(row.input, "asciimath");

  it.each(Object.entries(row.symbol))("lowercase %s reproduces the Symbol dispatch", (lang, o) => {
    // Every Symbol row at this pin is a result; a row that raises needs its
    // own class mapping before it can be asserted, so it fails here instead.
    expect(o.raises).toBeUndefined();
    const formula = build();
    expect(formula.toDisplay(lang)).toBe(o.result);
  });

  it.each(Object.entries(row.nativeUpcaseString))(
    "uppercase %s is the placeholder, as native Ruby returns for a String",
    (lang, o) => {
      expect(o.result).toBe(PLACEHOLDER);
      expect(build().toDisplay(lang.toUpperCase())).toBe(o.result);
    },
  );

  it("records the native-Ruby lowercase String result without substituting it", () => {
    for (const [lang, o] of Object.entries(row.nativeString)) {
      expect(o.result).toBe(PLACEHOLDER);
      expect(row.symbol[lang]?.result).toBeDefined();
      expect(build().toDisplay(lang)).toBe(row.symbol[lang]?.result);
    }
  });

  it.each(Object.entries(row.invalid))(
    "%s raises InvalidTypeError in the gem and UnsupportedFormatError here (divergence)",
    (lang, o) => {
      expect(o.raises).toBe("Plurimath::Math::InvalidTypeError");
      const formula = build();
      expect(() => formula.toDisplay(lang)).toThrow(UnsupportedFormatError);
    },
  );
});
